#pragma once

#include "vex/ir.hpp"

#include <memory>
#include <string>
#include <string_view>
#include <vector>

namespace vex {

enum class BackendKind {
    C
};

struct BackendResult {
    // Text generated by the backend (for example, C source or LLVM IR).
    std::string output;
    std::vector<Diagnostic> diagnostics;

    [[nodiscard]] bool has_errors() const noexcept;
};

// Code-generation boundary shared by all VEX backends. Implementations accept
// verified IR and must return diagnostics instead of emitting partial output
// after a code-generation error.
class Backend {
public:
    virtual ~Backend() = default;

    [[nodiscard]] virtual std::string_view name() const noexcept = 0;
    [[nodiscard]] virtual BackendResult emit(const IRModule& module) const = 0;
};

// Returns null when the requested backend has not been registered.
[[nodiscard]] std::unique_ptr<Backend> create_backend(BackendKind kind);

} // namespace vex
